def look_up(table, genre, key):
    """その社での呼び方を、実在する名前の中から選ぶ。無ければ空。"""
    for candidate in [genre['name']] + list(genre.get(key) or []):
        found = table.get(normalise(candidate))
        if found:
            return found
    return ''

